
export default {
  name: 'ImageUpload',
  
  props: {
    // Image display
    imagePath: {
      type: String,
      default: null
    },
    baseUrl: {
      type: String,
      default: ''
    },
    imageDisplaySize: {
      type: [String, Number],
      default: 200
    },
    imageDisplayHeight: {
      type: [String, Number],
      default: 150
    },
    
    // Upload configuration
    entityId: {
      type: [String, Number],
      required: true
    },
    uploadEndpoint: {
      type: String,
      required: true
    },
    deleteEndpoint: {
      type: String,
      default: ''
    },
    acceptedTypes: {
      type: String,
      default: 'image/*'
    },
    maxSizeMB: {
      type: Number,
      default: 5
    },
    
    // UI Configuration
    showHeader: {
      type: Boolean,
      default: true
    },
    showUploadSection: {
      type: Boolean,
      default: true
    },
    allowDelete: {
      type: Boolean,
      default: true
    },
    showGuidelines: {
      type: Boolean,
      default: true
    },
    
    // Text customization
    headerText: {
      type: String,
      default: 'ຮູບໂປຣໄຟລ໌'
    },
    uploadLabel: {
      type: String,
      default: 'ເລືອກຮູບໃໝ່'
    },
    previewLabel: {
      type: String,
      default: 'ຕົວຢ່າງຮູບທີ່ເລືອກ:'
    },
    placeholderText: {
      type: String,
      default: 'ບໍ່ມີຮູບ'
    },
    uploadButtonText: {
      type: String,
      default: 'ອັບໂຫລດຮູບ'
    },
    deleteButtonText: {
      type: String,
      default: 'ລຶບ'
    },
    uploadingText: {
      type: String,
      default: 'ກຳລັງອັບໂຫລດ...'
    },
    cancelButtonText: {
      type: String,
      default: 'ຍົກເລີກ'
    },
    
    // Icons
    headerIcon: {
      type: String,
      default: 'mdi-image-outline'
    },
    uploadIcon: {
      type: String,
      default: 'mdi-camera'
    },
    placeholderIcon: {
      type: String,
      default: 'mdi-image-outline'
    }
  },

  data() {
    return {
      selectedFile: null,
      previewUrl: null,
      uploading: false,
      deleting: false
    }
  },

  computed: {
    currentImageUrl() {
      if (this.imagePath) {
        return this.baseUrl ? `${this.baseUrl}/${this.imagePath}` : `/${this.imagePath}`
      }
      return null
    },

    canUpload() {
      return this.entityId && this.uploadEndpoint
    },

    guidelines() {
      const types = this.acceptedTypes.replace('image/', '').replace('*', 'JPG, PNG, GIF').toUpperCase()
      return `• ຮອງຮັບໄຟລ໌: ${types}<br>• ຂະໜາດສູງສຸດ: ${this.maxSizeMB}MB<br>• ແນະນຳຂະໜາດ: 400x400px`
    }
  },

  methods: {
    onFileSelected(file) {
      if (file) {
        try {
          this.validateFile(file)
          this.previewUrl = URL.createObjectURL(file)
        } catch (error) {
          this.$toast.error(error.message)
          this.clearSelectedFile()
        }
      } else {
        this.clearSelectedFile()
      }
    },

    validateFile(file) {
      // Validate file type
      if (this.acceptedTypes !== 'image/*') {
        const allowedTypes = this.acceptedTypes.split(',').map(type => type.trim())
        if (!allowedTypes.includes(file.type)) {
          throw new Error('ປະເພດໄຟລ໌ບໍ່ຮອງຮັບ')
        }
      } else {
        const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif']
        if (!allowedTypes.includes(file.type)) {
          throw new Error('ກະລຸນາເລືອກໄຟລ໌ຮູບພາບ (JPG, PNG, GIF)')
        }
      }

      // Validate file size
      const maxSize = this.maxSizeMB * 1024 * 1024
      if (file.size > maxSize) {
        throw new Error(`ຂະໜາດໄຟລ໌ໃຫຍ່ເກີນໄປ (ສູງສຸດ ${this.maxSizeMB}MB)`)
      }
    },

    clearSelectedFile() {
      this.selectedFile = null
      if (this.previewUrl) {
        URL.revokeObjectURL(this.previewUrl)
        this.previewUrl = null
      }
      if (this.$refs.fileInput) {
        this.$refs.fileInput.reset()
      }
    },

    async handleUpload() {
      if (!this.selectedFile || !this.canUpload) return

      this.uploading = true

      try {
        const formData = new FormData()
        formData.append('profile_image', this.selectedFile)

        const response = await this.$axios.post(
          this.uploadEndpoint.replace(':id', this.entityId),
          formData,
          {
            headers: {
              'Content-Type': 'multipart/form-data'
            }
          }
        )

        this.$toast.success('ອັບໂຫລດຮູບສຳເລັດແລ້ວ')
        this.clearSelectedFile()
        
        // Emit success event with response data
        this.$emit('upload-success', response.data)

      } catch (error) {
        console.error('Upload error:', error)
        const errorMessage = error.response?.data?.message || 'ອັບໂຫລດຮູບບໍ່ສຳເລັດ'
        this.$toast.error(errorMessage)
        this.$emit('upload-error', error)
      } finally {
        this.uploading = false
      }
    },

    async handleDelete() {
      if (!this.deleteEndpoint) {
        this.$emit('delete-requested')
        return
      }

      try {
        const result = await this.$swal.fire({
          title: 'ຢືນຢັນການລຶບ',
          text: 'ທ່ານຕ້ອງການລຶບຮູບນີ້ແທ້ບໍ?',
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'ລຶບ',
          cancelButtonText: 'ຍົກເລີກ'
        })

        if (result.isConfirmed) {
          this.deleting = true

          await this.$axios.delete(this.deleteEndpoint.replace(':id', this.entityId))

          this.$toast.success('ລຶບຮູບສຳເລັດແລ້ວ')
          this.$emit('delete-success')
        }
      } catch (error) {
        console.error('Delete error:', error)
        const errorMessage = error.response?.data?.message || 'ລຶບຮູບບໍ່ສຳເລັດ'
        this.$toast.error(errorMessage)
        this.$emit('delete-error', error)
      } finally {
        this.deleting = false
      }
    }
  },

  beforeDestroy() {
    // Clean up preview URL
    if (this.previewUrl) {
      URL.revokeObjectURL(this.previewUrl)
    }
  }
}
